changes.after:
// FIXED41 R5: this is the one-time startup boundary for Tally-last sequencing.
// It deliberately excludes the continuously changing runtime Auto Import/Bank queues:
// those queues may refill forever after startup and therefore cannot be the release condition.
// Unlike the R3 shortcut, both central source discovery and startup recovery must actually
// finish before the five-second Tally authority loop is released.
public bool IsInitialLocalPreparationComplete =>
    _centralSourceStartupComplete &&
    _startupRecoveryComplete;

public bool IsLocalPreparationComplete =>
    IsInitialLocalPreparationComplete &&
    _salesPurchaseSourceInFlight.IsEmpty &&
    _salesPurchaseSetProcessors.IsEmpty &&
    _gstBootstrapInFlight.IsEmpty &&
    _queue.IsEmpty &&
    _activeFiles.IsEmpty &&
    _bankCachedProcessors.IsEmpty &&
    _bankCachedQueues.Values.All(queue => queue.IsEmpty);

changes.before:
_automationService.AttachLocalPreparationReadyProvider(() => _workspaceStateCache.IsStartupPreparationComplete);
// FIXED41 R3: the 5-second Tally authority loop has a one-time startup latch of its own.
// Release that latch when startup cache scheduling is complete; do not tie it to the
// continuously changing Auto Import/Bank/source queues. Those queues may remain active
// or refill for the entire application session and must never starve ALTERID authority.
_tallyCoordinator.AttachLocalPreparationReadyProvider(() => _workspaceStateCache.IsStartupPreparationComplete);

changes.after:
_automationService.AttachLocalPreparationReadyProvider(() => _workspaceStateCache.IsStartupPreparationComplete);
// FIXED41 R5: restore the proven Tally-last startup boundary without reintroducing the
// old runtime interlock. The coordinator releases only after workspace startup scheduling,
// central source discovery and startup recovery have completed once. Its own one-time latch
// then stays open permanently; normal Auto Import/Bank queues can refill without blocking
// later five-second ALTERID synchronization.
_tallyCoordinator.AttachLocalPreparationReadyProvider(() =>
    _workspaceStateCache.IsStartupPreparationComplete && _automationService.IsInitialLocalPreparationComplete);
